	for i := 0; i < submitters; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			<-start
			recorder := doRequest(t, router, http.MethodPost, "/api/v1/release-records", bodies[i])
			statuses[i] = recorder.Code
			bodiesOut[i] = recorder.Body.String()
