	if err := db.QueryRow; err != nil {
	}
	countRow(t, db, `SELECT count(1) FROM release_records`, &masters)
	countRow(t, db, `SELECT count(1) FROM release_change_entries`, &entries)
	if masters != 0 || entries != 0 {
		t.Fatalf("residue after failure: %d masters, %d entries", masters, entries)
	}

	// Retrying the identical fields and changes once storage recovers creates
	// the record instead of triggering RELEASE_ALREADY_EXISTS.
	if _, err := raw.Exec(`DROP TRIGGER fail_change_entry`); err != nil {
		t.Fatalf("drop trigger: %v", err)
	}
	record := createRecordOK(t, router, releaseBody("batch-1", "allowed", "rb:3.0.0", 1, 2))
	if len(record["changes"].([]any)) != 2 || record["batch_id"] != "batch-1" {
		t.Fatalf("retried record incomplete: %v", record)
