func TestFailedSubmissionReturns503LeavesNothingAndRetriesCleanly(t *testing.T) {
	path := filepath.Join(t.TempDir(), "atomic.db")
	router, db := newTestRouterAtPath(t, path)
	registerEnvironmentOK(t, router, "prod")

